<template>
<section class="task-schema" aria-label="DDL 与标签">
<p v-if="error" class="inline-alert danger" role="alert">{{ error }}</p><p v-if="message" role="status">{{ message }}</p>
<form @submit.prevent="saveTags"><h4>任务标签</h4><label>标签（每行一个）<textarea v-model="tagText" class="input" rows="3" :readonly="!editable" :disabled="!loaded || busy" placeholder="日报&#10;核心链路&#10;财务" /></label><p class="hint">最多 20 个标签，每个最多 40 字。标签保存在平台，用于列表分类搜索。</p><button v-if="editable" class="btn" :disabled="busy || !loaded">保存标签</button></form>
<form @submit.prevent="save"><h4>数据库表 DDL · {{ data.file || 'ddl/schema.sql' }}</h4><p class="hint">可在同一文件中维护多张表，建议注明表名、连接标识和用途。保存草稿不会执行 SQL，也不会改变已发布任务文件。</p><label>DDL 内容<textarea v-model="content" class="input mono ddl-editor" spellcheck="false" :readonly="!editable" :disabled="!loaded || busy" /></label><label v-if="editable">修改说明<input v-model="note" class="input" maxlength="500" placeholder="例如：订单表新增业务日期索引"></label><div class="filter-actions"><button v-if="editable" class="btn primary" :disabled="busy || !loaded || !note.trim()">保存 DDL 草稿</button><button v-if="editable" type="button" class="btn" :disabled="busy || !loaded" @click="importRemote">载入 GitLab 最新 DDL</button><button v-if="editable" type="button" class="btn" :disabled="busy || !data.current?.revision || dirty" @click="previewGit">预览 GitLab 提交</button></div><p class="hint">当前草稿版本 {{ data.current?.revision || 0 }} · {{ data.current?.actor || '已发布文件' }} {{ data.current?.at || '' }}。GitLab 写入需要令牌具备项目 API 写权限。</p></form>
<section v-if="preview"><h4>即将提交的 GitLab 差异</h4><p class="hint">分支 {{ preview.branch }} → {{ preview.target }}。提交后通过 GitLab 创建合并请求，合并后沿用任务发布流程。</p><pre class="log-pre">{{ preview.diff }}</pre><button class="btn primary" :disabled="busy || dirty" @click="submitGit">确认提交独立分支</button></section>
<p v-if="receipt"><a :href="receipt.url" target="_blank" rel="noopener noreferrer">在 GitLab 创建合并请求</a> · {{ receipt.commit }}</p>
<details class="disclosure"><summary>草稿与导入基线的差异</summary><div class="disclosure-body"><pre class="log-pre">{{ data.diff || '无差异' }}</pre></div></details>
<section><h4>DDL 修改历史（最近 100 版）</h4><div v-for="item in data.history || []" :key="item.revision" class="schema-history"><div><strong>v{{ item.revision }} · {{ item.note }}</strong><p class="hint">{{ item.actor }} · {{ item.at }}</p></div><button class="btn" @click="selected=item">查看版本</button><button v-if="editable" class="btn" :disabled="busy" @click="restore(item)">载入编辑器</button></div><p v-if="!data.history?.length" class="hint">暂无平台修改记录。首次保存会生成版本。</p><pre v-if="selected" class="log-pre">{{ selected.content }}</pre></section>
</section>
</template>
<script setup>
import {ref,onMounted,onBeforeUnmount} from 'vue';import {api} from '../api';import {useUnsavedChanges} from '../composables/useUnsavedChanges';
const props=defineProps({pid:String,editable:Boolean,confirm:Function});
const data=ref({}),content=ref(''),note=ref(''),tagText=ref(''),tagData=ref({}),error=ref(''),message=ref(''),busy=ref(false),loaded=ref(false),preview=ref(null),receipt=ref(null),selected=ref(null);let alive=true;
const {dirty,saved}=useUnsavedChanges(()=>content.value,()=>loaded.value && props.editable);
const {saved:tagsSaved}=useUnsavedChanges(()=>tagText.value,()=>loaded.value && props.editable);
async function load(){const [ddl,tags]=await Promise.all([api.taskDdl(props.pid),api.taskTags(props.pid)]);if(!alive)return;data.value=ddl;content.value=ddl.current.content;tagData.value=tags;tagText.value=tags.tags.join('\n');loaded.value=true;saved();tagsSaved();}
async function work(action){if(busy.value)return;busy.value=true;error.value='';try{await action();}catch(e){if(alive)error.value=e.message;}finally{busy.value=false;}}
function saveTags(){work(async()=>{tagData.value=await api.saveTaskTags(props.pid,{revision:tagData.value.revision,tags:tagText.value.split(/\r?\n/).map(v=>v.trim()).filter(Boolean)});tagText.value=tagData.value.tags.join('\n');tagsSaved();message.value='标签已保存，返回任务列表刷新后可搜索。';});}
function save(){work(async()=>{await api.changeTaskDdl(props.pid,{action:'save',revision:data.value.current.revision,content:content.value,note:note.value});const fresh=await api.taskDdl(props.pid);data.value=fresh;content.value=fresh.current.content;saved();note.value='';preview.value=null;message.value='DDL 草稿已保存并记录历史。';});}
async function importRemote(){if(!await props.confirm({title:'载入 GitLab 最新 DDL',message:'会用目标分支文件替换编辑器内容，并保存为新的平台历史版本。请先保存需要保留的编辑。',confirmText:'载入最新版本',danger:true}))return;work(async()=>{await api.changeTaskDdl(props.pid,{action:'import',revision:data.value.current.revision});const fresh=await api.taskDdl(props.pid);data.value=fresh;content.value=fresh.current.content;saved();preview.value=null;message.value='已载入 GitLab 最新 DDL，可继续编辑并保存。';});}
function previewGit(){work(async()=>{preview.value=await api.changeTaskDdl(props.pid,{action:'preview',revision:data.value.current.revision});receipt.value=null;});}
async function submitGit(){if(!await props.confirm({title:'提交 DDL 到 GitLab',message:'将预览的 DDL 提交到 '+preview.value.branch+' 独立分支，之后在 GitLab 审查合并。',confirmText:'提交独立分支'}))return;work(async()=>{receipt.value=await api.changeTaskDdl(props.pid,{action:'submit',token:preview.value.token});preview.value=null;message.value='DDL 已提交，点击链接创建合并请求。';});}
async function restore(item){if(dirty.value && !await props.confirm({title:'载入历史版本',message:'当前未保存的 DDL 将被编辑器中的历史内容替换。',confirmText:'载入版本',danger:true}))return;content.value=item.content;note.value='恢复自 v'+item.revision;preview.value=null;}
onMounted(()=>work(load));onBeforeUnmount(()=>alive=false);
</script>
<style scoped>.task-schema,.task-schema form,.task-schema section{display:grid;gap:16px}.task-schema h4,.task-schema p{margin:0}.task-schema label{display:grid;gap:8px}.ddl-editor{min-height:280px;tab-size:4;line-height:1.6}.schema-history{display:flex;flex-wrap:wrap;align-items:center;gap:12px;border-bottom:1px solid var(--line);padding:12px 0}.schema-history>div{flex:1;min-width:180px}.task-schema .log-pre{max-height:360px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere}</style>
